int *headAdj, *to, *nxtAdj;
long long *weight;
long long *dist;
HeapNode *heap;
int heapSize = 0;
int edgeCnt = 0;

void addEdge(int u, int v, long long w) {
    to[edgeCnt] = v;
    weight[edgeCnt] = w;
    nxtAdj[edgeCnt] = headAdj[u];
    headAdj[u] = edgeCnt++;
}

int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

void unite(int a, int b) {
    a = find(a);
    b = find(b);
    if (a == b) return;
    if (sz[a] < sz[b]) {
        int tmp = a;
        a = b;
        b = tmp;
    }
    parent[b] = a;
    sz[a] += sz[b];
}

void heap_push(long long d, int v) {
    int i = ++heapSize;
    while (i > 1) {
        int p = i >> 1;
        if (heap[p].d <= d) break;
        heap[i] = heap[p];
        i = p;
    }
    heap[i].d = d;
    heap[i].v = v;
}

