    HeapNode res = heap[1];
    HeapNode last = heap[heapSize--];
    int i = 1;
    while (1) {
        int c = i << 1;
        if (c > heapSize) break;
        if (c + 1 <= heapSize && heap[c + 1].d < heap[c].d) c++;
        if (heap[c].d >= last.d) break;
        heap[i] = heap[c];
        i = c;
    }
    heap[i] = last;
    return res;
}

